import type { RootSnapshot } from './types'

/**
 * Snapshot the state that lives *outside* the note DOM.
 *
 * Two different hosts, two different reasons:
 *
 *  - Side Notes writes its entire visual configuration as `--sn-*` custom
 *    properties and `data-sn-*` attributes on `document.documentElement`, and
 *    the numbering is generated by CSS `content: attr(data-sidenote-num)` gated
 *    on those attributes. Cloning `.markdown-reading-view` therefore drops every
 *    number and every width/size setting — this snapshot is what puts them back.
 *  - Obsidian writes the user's accent colour as inline custom properties on
 *    `<body>` (`setAccentColor`). The class list only records *which* theme is
 *    active, never the values derived from the appearance settings, so a
 *    body-class-only snapshot re-exports every note in the default accent
 *    (round 3.3.3).
 */

const SN_DATA_KEYS = [
	'snBadgeStyle',
	'snShowNumbers',
	'snFormat',
	'snHideFootnotes',
	'snHideFootnoteNumbers'
]

/**
 * Every `data-*` attribute of an element, verbatim.
 *
 * `data-he-*` is ours (the exporter's own markers); replaying it would be
 * harmless but pointless, and could collide with a freshly generated marker.
 * Everything else belongs to the app / a plugin / a snippet and is part of the
 * appearance state — dropping it changes which CSS rules match in the export.
 */
function dataAttributes(el: HTMLElement): Record<string, string> {
	const out: Record<string, string> = {}
	if (!el || typeof el.attributes === 'undefined') return out
	for (const attr of Array.from(el.attributes)) {
		if (!attr.name.startsWith('data-') || attr.name.startsWith('data-he-')) continue
		out[attr.name] = attr.value
	}
	return out
}

export function snapshotRoot(): RootSnapshot {
	const html = document.documentElement
	// Keep *all* html `data-*`, not just `data-sn-*`: a plugin may gate a rule
	// on any attribute (the same reason body attributes are now replayed).
	const data = dataAttributes(html)
	for (const key of SN_DATA_KEYS) {
		const value = html.dataset[key]
		if (value === undefined) continue
		// dataset.snShowNumbers  ->  data-sn-show-numbers
		const attr = `data-${kebab(key)}`
		if (data[attr] === undefined) data[attr] = value
	}

	return {
		className: html.className,
		style: html.getAttribute('style') ?? '',
		data,
		bodyClassName: document.body.className,
		bodyData: dataAttributes(document.body),
		bodyStyle: pickCustomProperties(document.body.getAttribute('style') ?? '')
	}
}

/**
 * Keep only custom-property declarations from an inline `style` string.
 *
 * Why a filter instead of copying the attribute verbatim: the exporter owns the
 * document geometry (see `BASE_CSS` / `CONTAINER_OWNED`). Replaying an inline
 * `height`/`overflow` from the live `<body>` would re-create the scroll box that
 * EI-01 removed. `--*` properties are theme state; everything else is layout.
 *
 * The scanner is paren/quote aware on purpose: a `url(data:…;base64,…)` value
 * contains a semicolon, and a naive `split(';')` would cut it in half and turn
 * one valid declaration into two broken ones.
 */
export function pickCustomProperties(style: string): string {
	if (!style) return ''
	const out: string[] = []
	for (const part of splitTopLevel(style)) {
		const trimmed = part.trim()
		if (!trimmed) continue
		const colon = trimmed.indexOf(':')
		if (colon <= 0) continue
		const name = trimmed.slice(0, colon).trim()
		if (!name.startsWith('--')) continue
		if (!trimmed.slice(colon + 1).trim()) continue
		out.push(trimmed)
	}
	return out.join('; ')
}

/** Split on `;` at paren depth 0, outside quotes. */
function splitTopLevel(style: string): string[] {
	const out: string[] = []
	let depth = 0
	let quote: '"' | "'" | null = null
	let current = ''

	for (let i = 0; i < style.length; i++) {
		const ch = style[i]
		if (quote) {
			current += ch
			if (ch === quote && style[i - 1] !== '\\') quote = null
			continue
		}
		if (ch === '"' || ch === "'") {
			quote = ch
			current += ch
			continue
		}
		if (ch === '(') depth++
		else if (ch === ')') depth = Math.max(0, depth - 1)
		else if (ch === ';' && depth === 0) {
			out.push(current)
			current = ''
			continue
		}
		current += ch
	}
	out.push(current)
	return out
}

/** Write a root snapshot onto a target `<html>` / `<body>` (export or preview). */
export function applyRootSnapshot(
	html: HTMLElement,
	snap: RootSnapshot,
	body?: HTMLElement | null
): void {
	html.className = snap.className
	if (snap.style) html.setAttribute('style', snap.style)
	for (const [name, value] of Object.entries(snap.data)) {
		html.setAttribute(name, value)
	}
	const target = body ?? (typeof document !== 'undefined' ? document.body : null)
	if (target && snap.bodyData) {
		for (const [name, value] of Object.entries(snap.bodyData)) {
			target.setAttribute(name, value)
		}
	}
}

function kebab(value: string): string {
	return value.replace(/[A-Z]/g, m => `-${m.toLowerCase()}`)
}
